mapper.select:
SELECT
    files_details.id,
    files_details.over_status,
    files_details.`status`,
    files_details.love,
    `name`,
    files_details.cover,
    files_details.files_id,
    files.is_folder,
    parent_id,
    file_path
FROM
    files_details
INNER JOIN files ON files_details.files_id = files.id AND files.deleted = 1

    INNER JOIN files_author
    ON files_author.files_id = files.id
    AND files_author.author_id = #{authorId}
    AND files_author.deleted = 1

WHERE files_details.deleted = 1

    and parent_id = #{parentId}


    and love = #{love}



    and files_details.`name` LIKE #{pattern}


    and files_details.`status` = #{status}


    and over_status = #{overStatus}


    and is_folder = #{isFolder}




            ORDER BY files_details.`name` ${sortOrder}


            ORDER BY series.last_read_time ${sortOrder}


            ORDER BY series.add_time ${sortOrder}



LIMIT #{offset},#{limit}

SELECT count(*) FROM files_details
INNER JOIN files ON files_details.files_id = files.id AND files.deleted = 1

    INNER JOIN files_author
    ON files_author.files_id = files.id
    AND files_author.author_id = #{authorId}
    AND files_author.deleted = 1

WHERE files_details.deleted = 1

    and parent_id = #{parentId}


    and love = #{love}



    and files_details.`name` LIKE #{pattern}


    and files_details.`status` = #{status}


    and over_status = #{overStatus}


    and is_folder = #{isFolder}

